INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d08e02a3-4f7c-499a-befc-7a2716f2d475', '21feff02-016d-46e2-bb9d-c27495133b1b', '100. óra: A sokszögek kerülete', 'Négyzet, téglalap, háromszög és sokszögek kerületének számítása (K).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "c6a44302-be7e-4ae0-81ae-f2b178467ef5", "text": "Mi a téglalap kerületének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "0008f3b6-f999-47bd-bd45-3dc46e6fe4e4", "text": "K = 2 * (a + b)", "isCorrect": true}, {"id": "3eb6bacf-5652-43c7-bc94-e3f268ac4bc2", "text": "K = a * b", "isCorrect": false}, {"id": "fd9b9f90-ab0b-4a82-8ea5-fd3945588a29", "text": "K = a + b", "isCorrect": false}, {"id": "b6761078-3182-44fb-a057-4d82a1ba17d4", "text": "K = 4 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "e0ed2084-bc85-475a-9e84-589f8a5c8493", "text": "Mi a négyzet kerületének képlete (''a'' oldallal)?", "type": "multiple-choice", "options": [{"id": "8a8ac370-b203-41b3-b3dd-c298b4cecd39", "text": "K = 4 * a", "isCorrect": true}, {"id": "65e8bbc9-ca8d-4cae-a28c-8b1a48371e4a", "text": "K = a * a", "isCorrect": false}, {"id": "5e1dd5c8-09e4-4542-a4c9-db5458d338ea", "text": "K = 2 * a", "isCorrect": false}, {"id": "6549e7c6-d11a-4a60-8bbc-0285ac627992", "text": "K = 6 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "24665280-6ad2-4d9f-ae4f-46b124eea94a", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap kerülete? (2 * (6 + 8))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "99e58b76-55e3-4940-a342-ad58460df167", "text": "Mennyi a 7 cm oldalú négyzet kerülete? (4 * 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "d9f67fa2-c1f8-4ae4-88d1-d6921c3cfacf", "text": "Mennyi a 3 cm, 4 cm, 5 cm oldalú háromszög kerülete? (3+4+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "649adaf4-ee6c-4422-8c16-4dab928e7b70", "text": "A kerület a sokszöget határoló oldalak hosszának összege.", "type": "true-false", "options": [{"id": "428650a8-263b-4cbe-b9fa-f194034015d4", "text": "Igaz", "isCorrect": true}, {"id": "6f53854d-87e5-4a15-b145-1db5f70801c7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ae98ba3f-3954-40c6-acdd-954812739261", "text": "Mennyi a 5 cm oldalú szabályos ötszög kerülete? (5 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('20b79de9-3377-4dbc-9cf3-8ed563b459d8', '21feff02-016d-46e2-bb9d-c27495133b1b', '101. óra: Feladatmegoldás', 'Összetett kerületszámítási és kerítésszámítási szöveges feladatok.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "93bf8c7b-185d-4c90-92e3-539e76f10837", "text": "Egy téglalap alakú kert hossza 20 m, szélessége 15 m. Hány méter kerítés övezi a kertet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "450a9b90-6ae1-4d0a-8e42-07957f73ea0f", "text": "Hány méter kerítés kell a 20m x 15m-es kerthez, ha hagyunk egy 2 m-es kaput? (70 - 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "68"}, {"id": "b91a36e9-2b3e-4b15-b8f3-215288d6c3b3", "text": "Egy négyzet alakú pálya kerülete 100 m. Hány méter hosszú a pálya egy oldala? (100 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "9e46d5f7-f28e-44d7-9fd4-11023f3ae038", "text": "Ha a téglalap kerülete 30 cm, és egyik oldala 5 cm, mekkora a másik oldal? (15 - 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "03841e19-ada4-4835-81e7-4be18ca8d56e", "text": "A sokszögek kerületét mindig hosszúság-mértékegységben (m, cm, mm) adjuk meg.", "type": "true-false", "options": [{"id": "f169fc6d-9179-438e-8684-32cad10d94fb", "text": "Igaz", "isCorrect": true}, {"id": "9b415cfc-0203-4079-8ef3-48ba3b385a81", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "77e8a9f1-ecb9-47b2-bf4d-97d485463809", "text": "Mennyi a 10 cm oldalú szabályos hatszög kerülete?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "dd9ef4a0-c57d-40f3-b274-78b7a72fcb40", "text": "A kerületszámításos feladatoknál az oldalaknak azonos mértékegységben kell lenniük.", "type": "true-false", "options": [{"id": "0f443c6f-f834-4e7c-965f-2d9a7ddfc57b", "text": "Igaz", "isCorrect": true}, {"id": "62cf38f5-e8df-4b0d-935d-2a15d3b09ca9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0ac2963d-ed28-4792-b9dd-0861e749fa88', '21feff02-016d-46e2-bb9d-c27495133b1b', '102. óra: A terület és a térfogat mérése', 'A terület és térfogat mértékegységei, lefedés, egységkockák, átváltások.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "0e3e7e8b-3eb6-443f-b8b7-5c1ca9a47738", "text": "Mi a terület alapvető mértékegysége az SI-ben?", "type": "multiple-choice", "options": [{"id": "eb6bb93a-9297-4f9f-b42a-087982679ae7", "text": "Négyzetméter (m²)", "isCorrect": true}, {"id": "501a431c-c140-4ff3-ac63-b307bc96197c", "text": "Méter (m)", "isCorrect": false}, {"id": "6de32917-cdd0-4882-aec5-24d364c59e52", "text": "Köbméter (m³)", "isCorrect": false}, {"id": "aed7ab46-7d5d-4aaf-a156-10d0587b8163", "text": "Liter (l)", "isCorrect": false}], "timeLimit": 15}, {"id": "dc3f984d-c3e0-4a3b-b4cc-852e98a733a8", "text": "Hány cm² 1 dm²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "3c8a66ed-8b77-49f9-84c9-44dab761db6c", "text": "Hány dm² 1 m²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "f2df8f2e-d2f8-41ff-adbc-a904e3193150", "text": "Hány dm³ 1 m³? (10 * 10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "8dc07f0e-3d60-4b3f-a118-7094beebb95a", "text": "1 liter űrtartalom pontosan 1 köbdeciméternek (1 dm³) felel meg.", "type": "true-false", "options": [{"id": "efa5681c-de7e-4178-aa99-ab4af34a4000", "text": "Igaz", "isCorrect": true}, {"id": "b2905681-ea1e-4ecf-80da-f1ddedaa39a4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c290570c-c949-4773-9710-9f6559653eff", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "9f5d797f-6dd6-4773-b5e2-05d12667cd75", "text": "A terület mértékegységei között a szomszédos váltószám 100 (területnél 10²).", "type": "true-false", "options": [{"id": "33608487-d9a9-4b2d-b042-3cf3a6738774", "text": "Igaz", "isCorrect": true}, {"id": "bbc23c9a-b1fc-47c7-ba0b-550bbe3a0ad5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4b290dd3-4d43-4630-9a25-adf71984ce21', '21feff02-016d-46e2-bb9d-c27495133b1b', '103. óra: Gyakorlóóra. A terület és a térfogat mérése', 'Terület- és térfogat-mértékegységek gyakorlása digitális feladatlapokon.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "0b621860-2e75-4d97-bfe5-5bdfb3c6a08f", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "00302cda-3f4b-4eda-885f-fa6988eff6d6", "text": "Hány cm³ 2 liter? (2 dm³ = 2000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "aa6db53e-844a-4a5a-8efe-0f7fe4212c00", "text": "Hány m² 500 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "a7b5a0ae-3531-4e5c-82de-4041d5cc19fb", "text": "Hány litere felel meg 3,5 dm³ víznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3.5"}, {"id": "dd99feb8-25ab-4758-8656-f61c617bf853", "text": "A térfogat mértékegységei között a szomszédos váltószám 1000 (10³).", "type": "true-false", "options": [{"id": "073489fe-2eab-4888-8a68-497b68cce521", "text": "Igaz", "isCorrect": true}, {"id": "3c24589b-888a-4448-8f8a-5bec8af682f3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2b5b398d-0d69-4c20-9d07-f3a04a9dc380", "text": "Hány dl 1 liter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "c2e0bf52-8699-4730-9dd6-940a71d90ac6", "text": "Hány ml 1 dm³ (1 liter)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('66376b5e-e9d7-461b-992c-42e1265da6e6', '21feff02-016d-46e2-bb9d-c27495133b1b', '104. óra: A sokszögek területe', 'Négyzet, téglalap és derékszögű háromszög területe (T).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "1488933e-7067-4e74-9697-95f4abdaf801", "text": "Mi a téglalap területének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "1530aa1b-6169-4567-8057-731d7849c581", "text": "T = a * b", "isCorrect": true}, {"id": "dbbd99c1-963c-4957-aae8-943bdef413bf", "text": "T = 2 * (a + b)", "isCorrect": false}, {"id": "caa5cf9f-a8c2-4976-bdc1-51bf8a7e2f67", "text": "T = a + b", "isCorrect": false}, {"id": "d9a697a3-ffd1-4a36-9dbb-19dd3293d18b", "text": "T = a * a * a", "isCorrect": false}], "timeLimit": 15}, {"id": "48a2f885-8076-4548-aaa1-3726f0f9abdf", "text": "Mi a négyzet területének képlete (''a'' oldallal)?", "type": "multiple-choice", "options": [{"id": "bcd94c55-a9d3-464b-82ec-5ccc4d95c175", "text": "T = a * a (a²)", "isCorrect": true}, {"id": "b364b7ba-acca-4276-8e21-6e1c1cd158d1", "text": "T = 4 * a", "isCorrect": false}, {"id": "6a86ba88-8b23-486b-be1b-c0f001178432", "text": "T = 2 * a", "isCorrect": false}, {"id": "a4f9cb5e-12de-475d-80bb-7676e1f0ba16", "text": "T = a * 10", "isCorrect": false}], "timeLimit": 15}, {"id": "53b76ab9-be53-4a8b-a07e-b7b38e09f766", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "aa85c35f-4fee-440d-abf0-97c2ad528648", "text": "Mennyi a 5 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "3d001dbe-7470-4521-a4e2-63bf2a54adc7", "text": "Mi a derékszögű háromszög területének képlete (a és b befogókkal)?", "type": "multiple-choice", "options": [{"id": "887e932c-e9a4-4083-8244-5397610d1b10", "text": "T = (a * b) / 2", "isCorrect": true}, {"id": "5382548d-b812-45b8-abae-6acc1618f360", "text": "T = a * b", "isCorrect": false}, {"id": "6cd53cf5-bb80-4211-82d4-a07c33ea75f3", "text": "T = a + b", "isCorrect": false}, {"id": "e52541fe-aa1a-4e61-bb19-ee2ac3d77c5d", "text": "T = 2 * a * b", "isCorrect": false}], "timeLimit": 15}, {"id": "441b1bb1-543f-40da-a52a-6edf7f2a623b", "text": "Mennyi a 6 cm és 8 cm befogójú derékszögű háromszög területe? ((6*8)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "ddb8fbb7-59b2-416a-ac8c-ae6cdbf4c2b6", "text": "A derékszögű háromszög területe a két befogójú téglalap területének fele.", "type": "true-false", "options": [{"id": "6af5dbd1-4d4b-40a7-a220-2f7b91b91d5a", "text": "Igaz", "isCorrect": true}, {"id": "68594563-2c85-4d4b-b1b0-7f424702bd54", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e22ef008-0ee5-4d7e-a775-a3fa8ac4ad93', '21feff02-016d-46e2-bb9d-c27495133b1b', '105. óra: Feladatmegoldás', 'Kerület- és területszámítási feladatok, lakóház és szobapadló tervezése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "51b2547c-2489-43ce-a989-99ea5f4e93ca", "text": "Egy 5 m hosszú és 4 m széles szobába szőnyeget fektetünk. Hány m² a szoba területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "68a99f20-a864-4c7b-b03d-1fcf90e7a4c1", "text": "Ha a parketta ára 5000 Ft/m², mennyibe kerül a 20 m²-es szoba parkettázása?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100000"}, {"id": "97ac7d39-243d-4609-8ff5-be4e20a287cf", "text": "Hány méter szegélylécre van szükség a 5m x 4m-es szobához (kerület)? (2*(5+4))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "b43cf075-daf3-4c92-98d9-9ba285233ff3", "text": "Egy négyzet alakú szoba területe 36 m². Hány méter hosszú a szoba egy oldala?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "178018c2-cdd2-4a99-b3c7-3767b62e5c31", "text": "A terület számításához a méreteket azonos mértékegységre kell hozni a szorzás előtt.", "type": "true-false", "options": [{"id": "b6faa39d-f536-4c47-a77f-7a44f87ccbdb", "text": "Igaz", "isCorrect": true}, {"id": "37d7e88d-f649-43c7-8d57-9467fc76ad5e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b6ed94a5-fa5f-4787-93db-bec5cd03b5cf", "text": "Mennyi a 10 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "2112c94f-f414-4d34-a9f0-7b1eef5b40dd", "text": "A lakástervezésben a m² alapvető fontosságú.", "type": "true-false", "options": [{"id": "776f83da-92aa-4db8-81d2-06d9517a05f6", "text": "Igaz", "isCorrect": true}, {"id": "3e5694a8-1841-4c83-aa24-2f7415eb1ffc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8e98e4ff-8144-401a-9900-7801661d252b', '21feff02-016d-46e2-bb9d-c27495133b1b', '106. óra: Alakzatok a térben', 'Testek elnevezései (kocka, téglatest, hasáb, piramis), él, lap, csúcs, nézetek (elölnézet, felülnézet, oldalnézet).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "69ccf72a-8716-4636-a98c-23972fa2fffb", "text": "Hány lapja van a téglatestnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "4cf0d605-f8cc-4a33-b63e-2350fed49e11", "text": "Hány csúcsa van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "f35a45d8-bafc-44f0-8506-880f596aca9e", "text": "Hány éle van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "1dbf9a99-7266-4efc-9bd6-7d4ba1e740d5", "text": "A kocka minden lapja egyenlő négyzet.", "type": "true-false", "options": [{"id": "63f9b7f5-4bc0-4b59-b00b-18075f4b5def", "text": "Igaz", "isCorrect": true}, {"id": "8f62f8ae-9cfd-4789-8a73-d8849f84d070", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "44fea085-3593-46e5-9381-2580ed61bc2b", "text": "Milyen alakúak a téglatest lapjai?", "type": "multiple-choice", "options": [{"id": "48308c00-3b1b-4325-aff4-138be2e738b6", "text": "Téglalapok (melyek között négyzet is lehet)", "isCorrect": true}, {"id": "80dcfe72-5447-4da0-9807-c6a6bb1e9bcd", "text": "Háromszögek", "isCorrect": false}, {"id": "99ce5f9a-2df1-4bd6-aa72-8ea110911685", "text": "Körök", "isCorrect": false}, {"id": "b18a479e-528b-4466-9263-6a5ed8fc3463", "text": "Ötszögek", "isCorrect": false}], "timeLimit": 15}, {"id": "4a5025d0-c55c-4840-9059-4d63e4520925", "text": "A testek felülről, elölről és oldalról készített 2D vetületei a vetületi képek.", "type": "true-false", "options": [{"id": "ec87911d-4a92-47f1-9b85-3d1dc4f63ac5", "text": "Igaz", "isCorrect": true}, {"id": "8cf54785-cc35-45ae-a5a9-1c2cdcdb4e3e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d2ccf3c5-b85b-47a3-97bb-b7d3d49a8472", "text": "Hány lapja van a négyszög alapú gúlának (piramisnak)? (1 alap + 4 oldal)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0d429359-55f2-4ebc-937b-74b50c872b21', '21feff02-016d-46e2-bb9d-c27495133b1b', '107. óra: Testek felszíne', 'Kocka és téglatest felszínének kiszámítása (A vagy F).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "682c811c-969b-4860-b884-7537108f18c8", "text": "Mi a kocka felszínének képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "78996de3-7e30-4c3f-9860-8c43359a3a1e", "text": "F = 6 * a * a (6 * a²)", "isCorrect": true}, {"id": "59667289-d60f-4fa4-881d-c9929142a744", "text": "F = a * a * a", "isCorrect": false}, {"id": "744d7b7b-b661-44e5-b986-0db497e73493", "text": "F = 12 * a", "isCorrect": false}, {"id": "afb59c91-e9c4-4ba3-8e46-51f7e70e0dba", "text": "F = 4 * a²", "isCorrect": false}], "timeLimit": 15}, {"id": "dadb1ef6-7a3b-4c26-8c2a-d06d5bb5217b", "text": "Mi a téglatest felszínének képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "8566902f-d3fd-4f99-9aef-3dd5429c6201", "text": "F = 2 * (a*b + a*c + b*c)", "isCorrect": true}, {"id": "25204f76-c4fb-447b-9884-0417babe8ade", "text": "F = a * b * c", "isCorrect": false}, {"id": "e863b860-6217-4a25-be23-f61b26848d6c", "text": "F = 4 * (a + b + c)", "isCorrect": false}, {"id": "133b681c-94cf-465d-8d98-8d482e0c57fc", "text": "F = a*b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "55502d8a-cb5a-4d95-a440-2eb2ffd57e96", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "87ef169d-1c4a-46a2-9f1b-a60603d8796d", "text": "Mennyi a 2 cm, 3 cm, 4 cm élű téglatest felszíne? (2*(2*3 + 2*4 + 3*4) = 2*(6+8+12) = 2*26)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "52"}, {"id": "8dabd1fe-f12d-4a38-b5d9-59b5db10b56a", "text": "A felszín a testet határoló lapok területeinek összege.", "type": "true-false", "options": [{"id": "f80a397f-b07e-4696-b4c6-d1a355afd8ca", "text": "Igaz", "isCorrect": true}, {"id": "2ea6cd73-5f00-4faa-9839-e43678d05300", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "56988c27-e2f7-443a-ae49-ffb53dc5db06", "text": "A felszínt mindig terület-mértékegységben (cm², m²) adjuk meg.", "type": "true-false", "options": [{"id": "353b69af-d7df-4bdb-890b-c46cb585fb88", "text": "Igaz", "isCorrect": true}, {"id": "00411137-b04e-4bf5-b501-8abd3ca204ad", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b9183129-ea29-4ccf-b7ab-4787d65eb0d8", "text": "Mennyi a 10 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('43956919-b6c1-4bfa-bdd3-23afde439c01', '21feff02-016d-46e2-bb9d-c27495133b1b', '108. óra: Gyakorlóóra', 'Felszínszámítás gyakorlása hálók megrajzolásával és szerkesztőprogrammal.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "e1d5b1b3-0335-48b2-aa35-d54c7c226cdf", "text": "Hány négyzetből áll a kocka hálója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "284e3fa0-243a-40f6-a6ca-3f3878486498", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "da741b92-9298-4b84-9a12-a44eb16fc76a", "text": "Mennyi a 1 m, 2 m, 3 m élű téglatest felszíne? (2*(2+3+6) = 2*11)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "15261291-0ca3-459c-894c-01076cbd42da", "text": "A test hálójának területe megegyezik a test felszínével.", "type": "true-false", "options": [{"id": "e9897f17-ba21-40ea-bdde-194e96c8d22e", "text": "Igaz", "isCorrect": true}, {"id": "eb27fa1e-a7cc-4029-8829-005858a789de", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "80e53ae6-a7a9-4283-8b1b-69e6e5d57c9f", "text": "Mennyi a 5 cm élű kocka felszíne? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "6ce2a5d9-b51f-4970-9e08-815594dd6d1b", "text": "Dinamikus szerkesztőprogrammal a testek hálója kiteríthető és összehajtható.", "type": "true-false", "options": [{"id": "b0338cdd-4285-455c-832a-a6bd5477c293", "text": "Igaz", "isCorrect": true}, {"id": "22994842-206b-4f85-981c-c10f450a1a83", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "275f89b4-1af8-4949-896c-aaaff5c9f95f", "text": "A téglatest szemközti lapjai egyenlő területűek.", "type": "true-false", "options": [{"id": "a63271f8-db6a-4dc4-9e8d-ff66f1e90a97", "text": "Igaz", "isCorrect": true}, {"id": "c6386f3a-a38c-45b2-92e6-ff42745229a2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0752f1eb-a034-43be-8517-c80c1c3f8a04', '21feff02-016d-46e2-bb9d-c27495133b1b', '109. óra: Felszínszámítással kapcsolatos gyakorlati feladatok', 'Dobozok lefestése, csomagolópapír szükséglet kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "965f9953-4a0f-4863-b304-7096338490ce", "text": "Egy 10 cm x 20 cm x 30 cm-es téglatest dobozt befestünk. Hány cm² felületet kell lefesteni? (2*(200+300+600) = 2*1100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2200"}, {"id": "6f676827-4968-4621-a6cc-4a52f1af6262", "text": "Hány cm² csomagolópapír kell egy 5 cm élű kocka alakú ajándék becsomagolásához (ráhagyás nélkül)? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "7ffc24a6-9b42-4db8-83c9-ec92f57f7b34", "text": "Ha a festékből 1 m²-re 200 g kell, hány gramm festék kell 5 m² felszínre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "0d63de5d-06c1-449c-94e0-66be0a0868a1", "text": "Csomagoláskor a veszteség és az átfedés miatt érdemes a kiszámított felszínnél kb. 10-20%-kal több papírral számolni.", "type": "true-false", "options": [{"id": "239346a0-c102-4c50-bdf6-1873a9903e5e", "text": "Igaz", "isCorrect": true}, {"id": "46dd6af3-7410-445f-9e42-0f4c094348c8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "602cb900-a8c3-4895-beec-13e4727cff5b", "text": "Mennyi a 2 cm élű kocka felszíne? (6 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "96f84312-5b0b-40d1-b647-9c014f755407", "text": "A dobozok tervezésénél az anyagszükségletet a felszín határozza meg.", "type": "true-false", "options": [{"id": "456ae09a-890b-4d2c-92ae-2e8812414fce", "text": "Igaz", "isCorrect": true}, {"id": "8acf6443-edc0-4928-87a3-74421c982196", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c1291d94-d1c0-42a0-aa48-077e8f3d90c5", "text": "Mennyi a 1 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW());